/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

M2C_UNK setActorCommandState(s32, M2C_UNK);                /* extern */
M2C_UNK setActorAnimation(s32, M2C_UNK);                /* extern */
s32 resetActorActionState();                                /* extern */

/* If the actor's action state was reset, switch it to command 0x14D and animation 1. */ void playActorHitReaction(s32 actor) {
    if ((resetActorActionState() << 0x18) != 0) {
        setActorCommandState(actor, 0x14D);
        setActorAnimation(actor, 1);
    }
}
